def orfs(s,strand,minaa=80):
    out=[]
    for f in range(3):
        t=translate(s[f:])
        start=0
        for j,ch in enumerate(t):
            if ch=='*':
                if j-start>=minaa: out.append((f,start,j,t[start:]))
                start=j+1
        if len(t)-start>=minaa: out.append((f,start,len(t),t[start:]))
    L=len(s)
    res=[]
    for f,a,b,p in out:
        if strand=='+':
            s0=f+3*a; s1=f+3*b-1
