def dots(a,b,w=30):
    hits=[]
    for i in range(0,len(a)-w,5):
        k=a[i:i+w]
        j=b.find(k)
        while j!=-1:
            if abs(i-j)>w: hits.append((i,j))
            j=b.find(k,j+1)
    return hits
