def poscomp(s):
    tab={0:{'A':0,'C':0,'G':0,'T':0},1:{'A':0,'C':0,'G':0,'T':0},2:{'A':0,'C':0,'G':0,'T':0}}
    n=0
    for i in range(0,len(s)-2,3):
        for k in range(3):
            tab[k][s[i+k]]+=1
        n+=1
    return tab,n
def chi2(tab,n):
    # test independence position vs base
    tot={b:tab[0][b]+tab[1][b]+tab[2][b] for b in "ACGT"}
    N=3*n
    chi=0
    for k in range(3):
        for b in "ACGT":
            exp=n*tot[b]/N
            chi+=(tab[k][b]-exp)**2/exp
    return chi
def show(name,s):
    tab,n=poscomp(s)
    print(name, "n codons",n, "chi2",round(chi2(tab,n),1))
    for k in range(3):
        print("   pos",k,[round(tab[k][b]/n,3) for b in "ACGT"])
